n = randint(20, 255)
sens = choice(["d2b", "b2d", "d2h", "h2d"])
if sens == "d2b":
    q, rep, cible = f"l'entier {n}", tobase(n, 2), "en binaire"
elif sens == "b2d":
    q, rep, cible = f"le nombre binaire {group(tobase(n, 2, 8))}", str(n), "en décimal"
elif sens == "d2h":
    q, rep, cible = f"l'entier {n}", tobase(n, 16), "en hexadécimal"
else:
    q, rep, cible = f"le nombre hexadécimal {tobase(n, 16)}", str(n), "en décimal"
